    png.Encode(f, img)
    f.Close()
    // 8x8 checker for more tests
    img8 := image.NewRGBA(image.Rect(0,0,8,8))
    for y:=0;y<8;y++{
        for x:=0;x<8;x++{
            if (x+y)%2==0 {
                img8.Set(x,y, color.RGBA{0,0,0,255})
            } else {
                img8.Set(x,y, color.RGBA{255,255,255,255})
            }
        }
    }
    f,_=os.Create("/tmp/test8x8check.png")
    png.Encode(f, img8)
    f.Close()
    // 8x1 gradient 0..255
    imgG := image.NewRGBA(image.Rect(0,0,8,1))
    for x:=0;x<8;x++{
        v:=uint8(x*255/7)
        imgG.Set(x,0, color.RGBA{v,v,v,255})
    }
    f,_=os.Create("/tmp/test8x1.png")
    png.Encode(f, imgG)
    f.Close()
    // 1x8 gradient
    imgGV := image.NewRGBA(image.Rect(0,0,1,8))
    for y:=0;y<8;y++{
        v:=uint8(y*255/7)
        imgGV.Set(0,y, color.RGBA{v,v,v,255})
    }
    f,_=os.Create("/tmp/test1x8.png")
    png.Encode(f, imgGV)
    f.Close()
    println("done3")
}
