import subprocess, re
def get_pixels(tr,tc,img):
    r=subprocess.run(['./executable','-tr',str(tr),'-tc',str(tc),img], capture_output=True, timeout=5)
    s=r.stdout.decode()
    lines=s.splitlines()
    pixels=[]
    for line in lines:
        pat=re.findall(r'\x1b\[48;2;(\d+);(\d+);(\d+)m\x1b\[38;2;(\d+);(\d+);(\d+)m▄', line)
        top=[int(a) for a,b,c,_,_,_ in pat]
        bot=[int(d) for _,_,_,d,e,f in pat]
        pixels.append(top)
        pixels.append(bot)
    return pixels

print("4x1 (0,85,170,255) -> tc=4 (identity? should be same):")
print(get_pixels(2,4,"/tmp/test4x1.png")[0])

print("1x4 (0,85,170,255) -> tr=2 (height 4, identity?):")
pix=get_pixels(2,2,"/tmp/test1x4.png")
print([row[0] for row in pix])

print("8x1 -> tc=8 identity?")
print(get_pixels(2,8,"/tmp/test8x1.png")[0])
print("expected:", [int(x*255/7) for x in range(8)])

print("1x8 -> tr=4 (height 8) identity?")
pix=get_pixels(4,2,"/tmp/test1x8.png")
print([row[0] for row in pix])
print("expected:", [int(y*255/7) for y in range(8)])
PY"}

