import subprocess

def fit_dims(tr,tc,img):
    r=subprocess.run(['./executable','-tr',str(tr),'-tc',str(tc),'-s','2',img], capture_output=True, timeout=10)
    if r.returncode!=0:
        return f"ERR {r.stderr.decode()[:80]!r}"
