package main

import (
    "fmt"
    "math"
)

func sinc(x float64) float64 {
    if x == 0 {
        return 1
    }
    return math.Sin(math.Pi*x) / (math.Pi * x)
}

func lanczos(x float64, a int) float64 {
    if math.Abs(x) >= float64(a) {
        return 0
    }
    return sinc(x) * sinc(x/float64(a))
}

// scale 1D: src [0,255] with 2 pixels, dst N, using Lanczos with clamp edge, center mapping
func scale1D(src []float64, dstN int, a int) []int {
    srcN := len(src)
    dst := make([]int, dstN)
    scale := float64(srcN) / float64(dstN)
    // For upscaling (scale<1), kernel scaled? Standard: for downscaling, kernel radius scaled by 1/scale, and kernel scaled.
    // For upscaling, kernel radius = a, no scaling.
    // For downscaling, kernel radius = a/scale? Actually a/scale? Let's use standard: 
    // scale <1 (upscale): kernel(x - srcPos) with radius a
    // scale >1 (downscale): kernel((x - srcPos)/scale)/scale with radius a*scale
    // Here src=2, dst>=2, so scale<=1 (upscale or same), so no downscale handling needed for these tests.
    for i := 0; i < dstN; i++ {
        // center mapping: srcPos = (i+0.5)*srcN/dstN - 0.5
        srcPos := (float64(i)+0.5)*float64(srcN)/float64(dstN) - 0.5
        var sum, wsum float64
        // kernel support: srcPos-a+1 to srcPos+a
        // For Lanczos with clamp, iterate over src indices that contribute
        // Determine range: floor(srcPos-a+1) to ceil(srcPos+a)
        start := int(math.Floor(srcPos - float64(a) + 1))
        end := int(math.Ceil(srcPos + float64(a)))
        for j := start; j <= end; j++ {
            // clamp edge: j_clamped = min(max(j,0),srcN-1)
            jc := j
            if jc < 0 { jc = 0 }
            if jc >= srcN { jc = srcN-1 }
            w := lanczos(srcPos-float64(j), a)
            // Note: for clamp, should we use j or jc for weight? Weight based on original j distance, value from clamped.
            // Standard clamp: weight computed from distance to j, value from clamped.
            // But some implementations compute weight from distance to jc? No, from j.
            sum += src[jc] * w
            wsum += w
        }
        v := sum / wsum
        // clamp and round
        if v < 0 { v = 0 }
        if v > 255 { v = 255 }
        dst[i] = int(math.Round(v))
    }
    return dst
}

func main(){
    src := []float64{0,255}
    for _, n := range []int{2,3,4,5,6,7,8,9,10,12,14,16} {
        for _, a := range []int{2,3} {
            res := scale1D(src, n, a)
            fmt.Printf("Lanczos%d 2->%d: %v\n", a, n, res)
        }
    }
}
