package main

import (
    "fmt"
    "math"
)

func mitchell(x float64, B, C float64) float64 {
    ax := math.Abs(x)
    if ax < 1 {
        return ((12-9*B-6*C)*ax*ax*ax + (-18+12*B+6*C)*ax*ax + (6-2*B)) / 6
    } else if ax < 2 {
        return ((-B-6*C)*ax*ax*ax + (6*B+30*C)*ax*ax + (-12*B-48*C)*ax + (8*B+24*C)) / 6
    }
    return 0
}

func scale1D(src []float64, dstN int, B, C float64) []int {
    srcN := len(src)
    dst := make([]int, dstN)
    for i := 0; i < dstN; i++ {
        srcPos := (float64(i)+0.5)*float64(srcN)/float64(dstN) - 0.5
        var sum, wsum float64
        start := int(math.Floor(srcPos - 2 + 1))
        end := int(math.Ceil(srcPos + 2))
        for j := start; j <= end; j++ {
            jc := j
            if jc < 0 { jc = 0 }
            if jc >= srcN { jc = srcN-1 }
            w := mitchell(srcPos-float64(j), B, C)
            sum += src[jc] * w
            wsum += w
        }
        v := sum / wsum
        if v < 0 { v = 0 }
        if v > 255 { v = 255 }
        dst[i] = int(math.Round(v))
    }
    return dst
}

func bilinear(src []float64, dstN int) []int {
    srcN := len(src)
    dst := make([]int, dstN)
    for i := 0; i < dstN; i++ {
        srcPos := (float64(i)+0.5)*float64(srcN)/float64(dstN) - 0.5
        // clamp srcPos to [0, srcN-1]
        if srcPos < 0 { srcPos = 0 }
        if srcPos > float64(srcN-1) { srcPos = float64(srcN-1) }
        j0 := int(math.Floor(srcPos))
        j1 := j0+1
        if j1 >= srcN { j1 = srcN-1 }
        t := srcPos - float64(j0)
        v := src[j0]*(1-t) + src[j1]*t
        dst[i] = int(math.Round(v))
    }
    return dst
}

func main(){
    src := []float64{0,255}
    fmt.Println("Bilinear:")
    for _, n := range []int{4,6,8,10} {
