func bilinear(src []float64, dstN int) []int {
    srcN := len(src)
    dst := make([]int, dstN)
    for i := 0; i < dstN; i++ {
        srcPos := (float64(i)+0.5)*float64(srcN)/float64(dstN) - 0.5
        // clamp srcPos to [0, srcN-1]
        if srcPos < 0 { srcPos = 0 }
        if srcPos > float64(srcN-1) { srcPos = float64(srcN-1) }
        j0 := int(math.Floor(srcPos))
        j1 := j0+1
