    // Let's implement simple: while j<0 or j>=n, reflect.
    for j<0 || j>=n {
        if j<0 { j = -j }
        if j>=n { j = 2*n - j - 2 }
    }
    return j
}
func reflectIdx(j, n int) int {
    // reflect with repeating edge: -1->0, -2->1, N->N-1, N+1->N-2
    for j<0 || j>=n {
        if j<0 { j = -j-1 }
        if j>=n { j = 2*n - j -1 }
    }
    return j
}
func wrap(j,n int) int {
    j%=n
    if j<0{j+=n}
    return j
}

