        if j>=n { j = 2*n - j -1 }
    }
    return j
}
func clampIdx(j,n int) int {
    if j<0{return 0}
    if j>=n{return n-1}
    return j
}
func mirrorIdx(j,n int) int {
    if n==1{return 0}
    for j<0 || j>=n {
        if j<0 { j = -j }
        if j>=n { j = 2*n - j - 2 }
    }
    return j
}
