    if n==1{return 0}
    for j<0 || j>=n {
        if j<0 { j = -j }
        if j>=n { j = 2*n - j - 2 }
    }
    return j
}
func wrapIdx(j,n int) int {
    j%=n
    if j<0{j+=n}
    return j
}

