package main

import (
    "fmt"
    "math"
)

func sinc(x float64) float64 {
    if x == 0 { return 1 }
    return math.Sin(math.Pi*x) / (math.Pi * x)
}
func lanczos(x float64, a int) float64 {
    if math.Abs(x) >= float64(a) { return 0 }
    return sinc(x) * sinc(x/float64(a))
}

func scale(src []float64, dstN, a int) []int {
    srcN:=len(src)
    scale:=float64(srcN)/float64(dstN)
    var radius float64
    if scale>1 {radius=float64(a)*scale} else {radius=float64(a)}
    dst:=make([]int, dstN)
    for i:=0;i<dstN;i++{
        srcPos:=(float64(i)+0.5)*scale-0.5
        var sum,wsum float64
        start:=int(math.Floor(srcPos-radius+1))
        end:=int(math.Ceil(srcPos+radius))
        for j:=start;j<=end;j++{
            if j<0 || j>=srcN {continue}
            var w float64
            if scale>1 {w=lanczos((srcPos-float64(j))/scale,a)/scale} else {w=lanczos(srcPos-float64(j),a)}
            sum+=src[j]*w
            wsum+=w
        }
        v:=sum/wsum
        if v<0{v=0}
        if v>255{v=255}
        dst[i]=int(math.Round(v))
    }
    return dst
}

func main(){
    fmt.Printf("[0,255]->6: %v, last4 %v\n", scale([]float64{0,255},6,3), scale([]float64{0,255},6,3)[2:])
    fmt.Printf("[128,255]->6: %v, last4 %v\n", scale([]float64{128,255},6,3), scale([]float64{128,255},6,3)[2:])
