func isHexDigit(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}
func hexVal(c byte) int {
	if c >= '0' && c <= '9' {
		return int(c - '0')
	}
	if c >= 'a' && c <= 'f' {
		return int(c-'a') + 10
	}
	return int(c-'A') + 10
}
func parseHexByte(s string) int {
	// s length 2, hex digits
	return hexVal(s[0])*16 + hexVal(s[1])
}

func parseMatte(s string) (r, g, b uint8, ok bool) {
	if s == "" {
		return 0, 0, 0, true
	}
	n := len(s)
	if n == 1 || n == 2 || n == 4 {
		return 0, 0, 0, false
	}
	if n == 3 {
		for i := 0; i < 3; i++ {
			if !isHexDigit(s[i]) {
				return 0, 0, 0, false
			}
		}
		rv := hexVal(s[0])*17
		gv := hexVal(s[1])*17
		bv := hexVal(s[2])*17
		return uint8(rv), uint8(gv), uint8(bv), true
	}
	// n >=5 or n==0 handled, n==1,2,4 already false. n==3 handled. So n>=5 (including 5,6,7,...)
	if n >= 5 {
		for i := 0; i < 5; i++ {
			if !isHexDigit(s[i]) {
				return 0, 0, 0, false
			}
		}
		if n == 5 {
			rv := parseHexByte(s[0:2])
			gv := parseHexByte(s[2:4])
			bv := hexVal(s[4])
			return uint8(rv), uint8(gv), uint8(bv), true
		}
		// n>=6: check first 6 all hex?
		first6ok := true
		for i := 0; i < 6; i++ {
			if !isHexDigit(s[i]) {
				first6ok = false
				break
			}
		}
		if first6ok {
			rv := parseHexByte(s[0:2])
			gv := parseHexByte(s[2:4])
			bv := parseHexByte(s[4:6])
			return uint8(rv), uint8(gv), uint8(bv), true
		}
		// fallback to first 5 as 2+2+1 (since first 5 valid, index5 invalid)
		rv := parseHexByte(s[0:2])
		gv := parseHexByte(s[2:4])
		bv := hexVal(s[4])
		return uint8(rv), uint8(gv), uint8(bv), true
	}
	return 0, 0, 0, false
}

func isTTY() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getWinsize() (rows, cols int, ok bool) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(syscall.Stdout), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0, false
	}
	return int(ws.Row), int(ws.Col), true
}

// Lanczos
func sinc(x float64) float64 {
	if x == 0 {
		return 1
	}
	return math.Sin(math.Pi*x) / (math.Pi * x)
}
func lanczosK(x float64, a int) float64 {
	if math.Abs(x) >= float64(a) {
		return 0
	}
	return sinc(x) * sinc(x/float64(a))
}

// scale 1D float64 src to dstN with Lanczos a=3, skip outer, center mapping, downscale handling
func scale1DLanczos(src []float64, dstN, a int) []float64 {
	srcN := len(src)
	scale := float64(srcN) / float64(dstN)
	var radius float64
	if scale > 1 {
		radius = float64(a) * scale
	} else {
		radius = float64(a)
	}
	dst := make([]float64, dstN)
	for i := 0; i < dstN; i++ {
		srcPos := (float64(i)+0.5)*scale - 0.5
		var sum, wsum float64
		start := int(math.Floor(srcPos - radius + 1))
		end := int(math.Ceil(srcPos + radius))
		for j := start; j <= end; j++ {
			if j < 0 || j >= srcN {
				continue
			}
			var w float64
			if scale > 1 {
				w = lanczosK((srcPos-float64(j))/scale, a) / scale
			} else {
				w = lanczosK(srcPos-float64(j), a)
			}
			sum += src[j] * w
			wsum += w
		}
		if wsum == 0 {
			dst[i] = 0
		} else {
			dst[i] = sum / wsum
		}
	}
	return dst
}

func clampRound(v float64) uint8 {
	if v < 0 {
		v = 0
	}
	if v > 255 {
		v = 255
	}
	return uint8(math.Round(v))
}

// Resize RGB image (flattened, opaque) with Lanczos separable, intermediate uint8 rounding after horizontal
// srcW, srcH, src pixels R,G,B each 0-255 (opaque, already flattened with matte before scaling)
// dstW, dstH
func resizeLanczos(srcR, srcG, srcB []uint8, srcW, srcH, dstW, dstH int) (dstR, dstG, dstB []uint8) {
	// horizontal pass: srcH rows, each srcW -> dstW, with uint8 rounding intermediate
	interR := make([]uint8, dstW*srcH)
	interG := make([]uint8, dstW*srcH)
	interB := make([]uint8, dstW*srcH)
	for y := 0; y < srcH; y++ {
		rowR := make([]float64, srcW)
		rowG := make([]float64, srcW)
		rowB := make([]float64, srcW)
		for x := 0; x < srcW; x++ {
			idx := y*srcW + x
			rowR[x] = float64(srcR[idx])
			rowG[x] = float64(srcG[idx])
			rowB[x] = float64(srcB[idx])
		}
		scaledR := scale1DLanczos(rowR, dstW, 3)
		scaledG := scale1DLanczos(rowG, dstW, 3)
		scaledB := scale1DLanczos(rowB, dstW, 3)
		for x := 0; x < dstW; x++ {
			idx := y*dstW + x
			interR[idx] = clampRound(scaledR[x])
			interG[idx] = clampRound(scaledG[x])
			interB[idx] = clampRound(scaledB[x])
		}
	}
	// vertical pass: dstW cols, each srcH -> dstH
	dstR = make([]uint8, dstW*dstH)
	dstG = make([]uint8, dstW*dstH)
	dstB = make([]uint8, dstW*dstH)
	for x := 0; x < dstW; x++ {
		colR := make([]float64, srcH)
		colG := make([]float64, srcH)
		colB := make([]float64, srcH)
		for y := 0; y < srcH; y++ {
			idx := y*dstW + x
			colR[y] = float64(interR[idx])
			colG[y] = float64(interG[idx])
			colB[y] = float64(interB[idx])
		}
		scaledR := scale1DLanczos(colR, dstH, 3)
		scaledG := scale1DLanczos(colG, dstH, 3)
		scaledB := scale1DLanczos(colB, dstH, 3)
		for y := 0; y < dstH; y++ {
			idx := y*dstW + x
			dstR[idx] = clampRound(scaledR[y])
			dstG[idx] = clampRound(scaledG[y])
			dstB[idx] = clampRound(scaledB[y])
		}
	}
	return dstR, dstG, dstB
}

